  __guesses[pen] = (0)
  __guesses[e_n_0] = ([0, 1, 0])
  __guesses[aux] = ([1, 0, 0])
  __guesses[vsx] = (0)
  __guesses[vsy] = (0)
  isnothing(__ovr_Rleaf__guess) || (__guesses[Rleaf] = __ovr_Rleaf__guess)
  isnothing(__ovr_Rroot__guess) || (__guesses[Rroot] = __ovr_Rroot__guess)
  isnothing(__ovr_x__guess) || (__guesses[x] = __ovr_x__guess)
  isnothing(__ovr_y__guess) || (__guesses[y] = __ovr_y__guess)
  isnothing(__ovr_z__guess) || (__guesses[z] = __ovr_z__guess)
  if angular_state
    isnothing(__ovr_angles__guess) || (__guesses[angles] = __ovr_angles__guess)
  end
  if angular_state
    isnothing(__ovr_der_angles__guess) || (__guesses[der_angles] = __ovr_der_angles__guess)
  end
  if angular_state
    isnothing(__ovr_phi_roll__guess) || (__guesses[phi_roll] = __ovr_phi_roll__guess)
  end
  isnothing(__ovr_w_roll__guess) || (__guesses[w_roll] = __ovr_w_roll__guess)
  isnothing(__ovr_r_road_0__guess) || (__guesses[r_road_0] = __ovr_r_road_0__guess)
  isnothing(__ovr_f_wheel_0__guess) || (__guesses[f_wheel_0] = __ovr_f_wheel_0__guess)
  isnothing(__ovr_f_n__guess) || (__guesses[f_n] = __ovr_f_n__guess)
  isnothing(__ovr_f_lat__guess) || (__guesses[f_lat] = __ovr_f_lat__guess)
  isnothing(__ovr_f_long__guess) || (__guesses[f_long] = __ovr_f_long__guess)
  isnothing(__ovr_e_axis_0__guess) || (__guesses[e_axis_0] = __ovr_e_axis_0__guess)
  isnothing(__ovr_delta_0__guess) || (__guesses[delta_0] = __ovr_delta_0__guess)
  isnothing(__ovr_pen__guess) || (__guesses[pen] = __ovr_pen__guess)
  isnothing(__ovr_e_n_0__guess) || (__guesses[e_n_0] = __ovr_e_n_0__guess)
  isnothing(__ovr_e_lat_0__guess) || (__guesses[e_lat_0] = __ovr_e_lat_0__guess)
  isnothing(__ovr_e_long_0__guess) || (__guesses[e_long_0] = __ovr_e_long_0__guess)
  isnothing(__ovr_e_s_0__guess) || (__guesses[e_s_0] = __ovr_e_s_0__guess)
  isnothing(__ovr_s__guess) || (__guesses[s] = __ovr_s__guess)
  isnothing(__ovr_w__guess) || (__guesses[w] = __ovr_w__guess)
  isnothing(__ovr_v_0__guess) || (__guesses[v_0] = __ovr_v_0__guess)
  isnothing(__ovr_w_0__guess) || (__guesses[w_0] = __ovr_w_0__guess)
  isnothing(__ovr_aux__guess) || (__guesses[aux] = __ovr_aux__guess)
  isnothing(__ovr_omega__guess) || (__guesses[omega] = __ovr_omega__guess)
  isnothing(__ovr_R_eff__guess) || (__guesses[R_eff] = __ovr_R_eff__guess)
  isnothing(__ovr_vta__guess) || (__guesses[vta] = __ovr_vta__guess)
  isnothing(__ovr_vsx__guess) || (__guesses[vsx] = __ovr_vsx__guess)
  isnothing(__ovr_vsy__guess) || (__guesses[vsy] = __ovr_vsy__guess)
  isnothing(__ovr_sx__guess) || (__guesses[sx] = __ovr_sx__guess)
  isnothing(__ovr_sy__guess) || (__guesses[sy] = __ovr_sy__guess)
  isnothing(__ovr_sc__guess) || (__guesses[sc] = __ovr_sc__guess)
  isnothing(__ovr_q_n__guess) || (__guesses[q_n] = __ovr_q_n__guess)
  isnothing(__ovr_dfx0__guess) || (__guesses[dfx0] = __ovr_dfx0__guess)
  isnothing(__ovr_fxm__guess) || (__guesses[fxm] = __ovr_fxm__guess)
  isnothing(__ovr_fxs__guess) || (__guesses[fxs] = __ovr_fxs__guess)
  isnothing(__ovr_sxm__guess) || (__guesses[sxm] = __ovr_sxm__guess)
  isnothing(__ovr_sxs__guess) || (__guesses[sxs] = __ovr_sxs__guess)
  isnothing(__ovr_dfy0__guess) || (__guesses[dfy0] = __ovr_dfy0__guess)
  isnothing(__ovr_fym__guess) || (__guesses[fym] = __ovr_fym__guess)
  isnothing(__ovr_fys__guess) || (__guesses[fys] = __ovr_fys__guess)
  isnothing(__ovr_sym__guess) || (__guesses[sym] = __ovr_sym__guess)
  isnothing(__ovr_sys__guess) || (__guesses[sys] = __ovr_sys__guess)
  isnothing(__ovr_nL0__guess) || (__guesses[nL0] = __ovr_nL0__guess)
  isnothing(__ovr_sq0__guess) || (__guesses[sq0] = __ovr_sq0__guess)
  isnothing(__ovr_sqe__guess) || (__guesses[sqe] = __ovr_sqe__guess)
  isnothing(__ovr_P_len__guess) || (__guesses[P_len] = __ovr_P_len__guess)
  isnothing(__ovr_m_align__guess) || (__guesses[m_align] = __ovr_m_align__guess)
  isnothing(__ovr_gamma_c__guess) || (__guesses[gamma_c] = __ovr_gamma_c__guess)
  isnothing(__ovr_m_overturn__guess) || (__guesses[m_overturn] = __ovr_m_overturn__guess)
  isnothing(__ovr_ca__guess) || (__guesses[ca] = __ovr_ca__guess)
  isnothing(__ovr_sa__guess) || (__guesses[sa] = __ovr_sa__guess)
  isnothing(__ovr_f_c__guess) || (__guesses[f_c] = __ovr_f_c__guess)
  isnothing(__ovr_fx_tm__guess) || (__guesses[fx_tm] = __ovr_fx_tm__guess)
  isnothing(__ovr_fy_tm__guess) || (__guesses[fy_tm] = __ovr_fy_tm__guess)
  if low_speed_model
    isnothing(__ovr_brx__guess) || (__guesses[brx] = __ovr_brx__guess)
  end
  if low_speed_model
    isnothing(__ovr_bry__guess) || (__guesses[bry] = __ovr_bry__guess)
  end
  if low_speed_model
    isnothing(__ovr_brx_dot__guess) || (__guesses[brx_dot] = __ovr_brx_dot__guess)
  end
  if low_speed_model
    isnothing(__ovr_bry_dot__guess) || (__guesses[bry_dot] = __ovr_bry_dot__guess)
  end
  if low_speed_model
    isnothing(__ovr_f_coulomb__guess) || (__guesses[f_coulomb] = __ovr_f_coulomb__guess)
  end
  if low_speed_model
    isnothing(__ovr_fx_br__guess) || (__guesses[fx_br] = __ovr_fx_br__guess)
  end
  if low_speed_model
    isnothing(__ovr_fy_br__guess) || (__guesses[fy_br] = __ovr_fy_br__guess)
  end
  if low_speed_model
    isnothing(__ovr_br_scale__guess) || (__guesses[br_scale] = __ovr_br_scale__guess)
  end
  isnothing(__ovr_frblend__guess) || (__guesses[frblend] = __ovr_frblend__guess)

  ### Initialization Equations

  ### Assertions
  __assertions = []
  push!(__assertions, (abs(dot(e_n_0, e_axis_0)) < 0.99 => "Wheel lays nearly on the ground (which is a singularity) (at tmeasy_tire.dyad:330:3)"))

  ### Equations
  push!(__eqs, frame_a.r_0 ~ [x, y, z])
  push!(__eqs, Rleaf ~ frame_a.R)
  push!(__eqs, e_axis_0 ~ MultibodyComponents.resolve1(frame_a.R, [0, 0, 1]))
  push!(__eqs, aux ~ cross(e_n_0, e_axis_0))
  push!(__eqs, e_long_0 ~ aux / MultibodyComponents.norm_(aux))
  push!(__eqs, e_lat_0 ~ -cross(e_long_0, e_n_0))
  push!(__eqs, delta_0 ~ r_road_0 - frame_a.r_0)
  push!(__eqs, 0 ~ dot(delta_0, e_axis_0))
  push!(__eqs, 0 ~ dot(delta_0, e_long_0))
  push!(__eqs, pen ~ radius - dot(delta_0, cross(e_long_0, e_axis_0)))
  push!(__eqs, v_0 ~ ModelingToolkit.D_nounits(frame_a.r_0))
  push!(__eqs, omega ~ -w_roll)
  push!(__eqs, R_eff ~ (2 * radius + (radius - pen)) / 3)
  push!(__eqs, vta ~ R_eff * abs(omega) + vnum)
  push!(__eqs, vsx ~ dot(v_0, e_long_0) - omega * R_eff)
  push!(__eqs, vsy ~ dot(v_0, e_lat_0))
  push!(__eqs, sx ~ -vsx / vta)
  push!(__eqs, sy ~ -vsy / vta)
  push!(__eqs, sc ~ sqrt(sx ^ 2 + sy ^ 2))
  push!(__eqs, q_n ~ min(max(f_n, 0), pn_max) / pn)
  push!(__eqs, dfx0 ~ q_n * (2 * dfx0_pn - 0.5 * dfx0_p2n - (dfx0_pn - 0.5 * dfx0_p2n) * q_n))
  push!(__eqs, fxm ~ q_n * (2 * fxm_pn - 0.5 * fxm_p2n - (fxm_pn - 0.5 * fxm_p2n) * q_n))
  push!(__eqs, fxs ~ q_n * (2 * fxs_pn - 0.5 * fxs_p2n - (fxs_pn - 0.5 * fxs_p2n) * q_n))
  push!(__eqs, sxm ~ sxm_pn + (sxm_p2n - sxm_pn) * (q_n - 1))
  push!(__eqs, sxs ~ sxs_pn + (sxs_p2n - sxs_pn) * (q_n - 1))
  push!(__eqs, dfy0 ~ q_n * (2 * dfy0_pn - 0.5 * dfy0_p2n - (dfy0_pn - 0.5 * dfy0_p2n) * q_n))
  push!(__eqs, fym ~ q_n * (2 * fym_pn - 0.5 * fym_p2n - (fym_pn - 0.5 * fym_p2n) * q_n))
  push!(__eqs, fys ~ q_n * (2 * fys_pn - 0.5 * fys_p2n - (fys_pn - 0.5 * fys_p2n) * q_n))
  push!(__eqs, sym ~ sym_pn + (sym_p2n - sym_pn) * (q_n - 1))
  push!(__eqs, sys ~ sys_pn + (sys_p2n - sys_pn) * (q_n - 1))
  push!(__eqs, nL0 ~ nL0_pn + (nL0_p2n - nL0_pn) * (q_n - 1))
  push!(__eqs, sq0 ~ sq0_pn + (sq0_p2n - sq0_pn) * (q_n - 1))
  push!(__eqs, sqe ~ sqe_pn + (sqe_p2n - sqe_pn) * (q_n - 1))
  push!(__eqs, P_len ~ 2 * sqrt(radius * max(pen, 0)))
  push!(__eqs, m_align ~ -f_lat * P_len * SedanDemo.VehicleComponents.tmeasy_alignment_lever(abs(sy), nL0, sq0, sqe) * frblend)
  push!(__eqs, gamma_c ~ asin(max(min(dot(e_axis_0, e_n_0), 1), -1)))
  push!(__eqs, m_overturn ~ -c_gamma * gamma_c)
  push!(__eqs, ca ~ sx / max(sc, 0.000001))
  push!(__eqs, sa ~ sy / max(sc, 0.000001))
  push!(__eqs, f_c ~ SedanDemo.VehicleComponents.tmeasy_force(sc, sqrt((dfx0 * ca) ^ 2 + (dfy0 * sa) ^ 2), (mu_road / mu_0) * sqrt((sxm * ca) ^ 2 + (sym * sa) ^ 2), (mu_road / mu_0) * sqrt((fxm * ca) ^ 2 + (fym * sa) ^ 2), (mu_road / mu_0) * sqrt((sxs * ca) ^ 2 + (sys * sa) ^ 2), (mu_road / mu_0) * sqrt((fxs * ca) ^ 2 + (fys * sa) ^ 2)))
  push!(__eqs, fx_tm ~ f_c * ca)
  push!(__eqs, fy_tm ~ f_c * sa)
  push!(__eqs, frblend ~ SedanDemo.VehicleComponents.sine_step(dot(v_0, e_long_0), frblend_begin, 0, frblend_end, 1))
  push!(__eqs, f_wheel_0 ~ f_n * e_n_0 + f_long * e_long_0 + f_lat * e_lat_0)
  push!(__eqs, [0, 0, 0] ~ frame_a.f + MultibodyComponents.resolve2(frame_a.R, f_wheel_0))
  push!(__eqs, [0, 0, 0] ~ frame_a.tau + MultibodyComponents.resolve2(frame_a.R, cross(delta_0, f_wheel_0) - rolling_resistance * f_n * radius * tanh(w_roll) * e_axis_0 + m_align * e_n_0 + m_overturn * e_long_0))

  ### Control Structures
  if iscut
    push!(__eqs, MultibodyComponents.residue(Rleaf, Rroot) ~ residual)
  else
    push!(__eqs, Rleaf ~ Rroot)
  end
  if angular_state
    __guesses[angles] = ([0, 0, 0])
    __guesses[der_angles] = ([0, 0, 0])
    __guesses[phi_roll] = (0)
  else
  end
  if low_speed_model
    push!(__initialization_eqs, brx ~ 0)
    push!(__initialization_eqs, bry ~ 0)
  else
  end
  if surface
    push!(__eqs, surface_frame.f ~ [0, 0, 0])
    push!(__eqs, surface_frame.tau ~ [0, 0, 0])
    push!(__eqs, s ~ getindex(getproperty(surface_frame, :r_0), 1))
    push!(__eqs, w ~ getindex(getproperty(surface_frame, :r_0), 3))
    push!(__eqs, r_road_0 ~ surface_frame.r_0)
    push!(__eqs, e_n_0 ~ MultibodyComponents.resolve1(surface_frame.R, [0, 1, 0]))
    push!(__eqs, e_s_0 ~ MultibodyComponents.resolve1(surface_frame.R, [1, 0, 0]))
  else
    push!(__eqs, r_road_0 ~ [s, 0, w])
    push!(__eqs, e_n_0 ~ [0, 1, 0])
    push!(__eqs, e_s_0 ~ [1, 0, 0])
  end
  if angular_state
    push!(__eqs, Rroot ~ MultibodyComponents.RR(MultibodyComponents.axes_rotations(sequence, angles, der_angles)))
    push!(__eqs, der_angles ~ ModelingToolkit.D_nounits(angles))
    push!(__eqs, phi_roll ~ angles[2])
    push!(__eqs, w_roll ~ ModelingToolkit.D_nounits(phi_roll))
    push!(__eqs, w_0 ~ MultibodyComponents.resolve1(frame_a.R, MultibodyComponents.angular_velocity2(MultibodyComponents.axes_rotations(sequence, angles, der_angles))))
  else
    push!(__eqs, Rroot ~ frame_a.R)
    push!(__eqs, w_roll ~ dot(MultibodyComponents.angular_velocity2(MultibodyComponents.ori(frame_a)), [0, 0, 1]))
    push!(__eqs, w_0 ~ MultibodyComponents.angular_velocity1(MultibodyComponents.ori(frame_a)))
  end
  if elastic_contact
    push!(__eqs, f_n ~ max(0, c_z * pen + d_z * ModelingToolkit.D_nounits(pen)))
  else
    push!(__eqs, 0 ~ pen)
  end
  if low_speed_model
    push!(__eqs, f_coulomb ~ max((mu_road / mu_0) * f_n, 1))
    push!(__eqs, brx_dot ~ vsx - sigma0 * brx * abs(vsx) / f_coulomb)
    push!(__eqs, bry_dot ~ vsy - sigma0 * bry * abs(vsy) / f_coulomb)
    push!(__eqs, ModelingToolkit.D_nounits(brx) ~ brx_dot)
    push!(__eqs, ModelingToolkit.D_nounits(bry) ~ bry_dot)
    push!(__eqs, fx_br ~ -(sigma0 * brx + sigma1 * brx_dot))
    push!(__eqs, fy_br ~ -(sigma0 * bry + sigma1 * bry_dot))
    push!(__eqs, br_scale ~ min(1, f_coulomb / sqrt(fx_br ^ 2 + fy_br ^ 2 + 1e-12)))
    push!(__eqs, f_long ~ (1 - frblend) * fx_br * br_scale + frblend * fx_tm)
    push!(__eqs, f_lat ~ (1 - frblend) * fy_br * br_scale + frblend * fy_tm)
  else
    push!(__eqs, f_long ~ fx_tm)
    push!(__eqs, f_lat ~ fy_tm)
  end

  # Return completely constructed System
  return System(__eqs, ModelingToolkit.t_nounits, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export TMeasyWheelJoint
